/* ============================================
   GreenBean Coffee — Design System
   Brand Colors: #00824A (primary), #32462F (dark forest), #F3CEA1 (warm cream)
   ============================================ */

/* --- CSS Variables --- */
:root {
  /* Colors */
  --color-primary: #00824A;
  --color-primary-hover: #006B3D;
  --color-primary-light: #E6F4ED;
  --color-primary-10: rgba(0, 130, 74, 0.1);
  --color-primary-20: rgba(0, 130, 74, 0.2);
  --color-dark: #32462F;
  --color-dark-hover: #283A26;
  --color-dark-light: #4A5E47;
  --color-cream: #F3CEA1;
  --color-cream-light: #FAF0E4;
  --color-cream-dark: #D4A76A;
  --color-white: #FFFFFF;
  --color-warm-bg: #FAF7F2;
  --color-warm-bg-alt: #F5F0E8;
  --color-text: #1A1817;
  --color-text-secondary: #5C5A57;
  --color-text-muted: #8B8986;
  --color-border: #E0DCD5;
  --color-border-light: #EEEAE3;
  --color-error: #C0392B;
  --color-success: #00824A;
  --color-gold: #D4A76A;
  --color-gold-light: #F9F0E3;
  --color-star: #D4A76A;

  /* Typography */
  --font-heading: 'DM Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'DM Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;

  /* Font Sizes */
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.08), 0 4px 8px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 48px rgba(0,0,0,0.1), 0 8px 16px rgba(0,0,0,0.04);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 72px;
}

/* --- Reset --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

main {
  flex: 1;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  font-size: inherit;
}

input, select, textarea {
  font-family: inherit;
  font-size: inherit;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-text);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-2xl); }
h4 { font-size: var(--text-xl); }
h5 { font-size: var(--text-lg); }
h6 { font-size: var(--text-base); }

/* --- Container --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.container--narrow {
  max-width: 960px;
}

.container--wide {
  max-width: 1440px;
}

/* --- Header / Navigation --- */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border-light);
  height: var(--header-height);
  box-shadow: var(--shadow-sm);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: var(--text-xl);
  color: var(--color-primary);
  letter-spacing: -0.02em;
}

.header__logo svg {
  width: 36px;
  height: 36px;
}

.header__nav {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.header__nav-link {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.header__nav-link:hover,
.header__nav-link--active {
  color: var(--color-primary);
  background: var(--color-primary-10);
}

.header__actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.header__mobile-toggle {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--color-text);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--text-sm);
  font-weight: 600;
  line-height: 1.5;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
  min-height: 44px;
  letter-spacing: 0.01em;
}

.btn:active {
  transform: scale(0.97);
}

.btn--primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn--primary:hover {
  background: var(--color-primary-hover);
  box-shadow: var(--shadow-md);
}

.btn--outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn--outline:hover {
  background: var(--color-primary-10);
}

.btn--dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.btn--dark:hover {
  background: var(--color-dark-hover);
  box-shadow: var(--shadow-md);
}

.btn--cream {
  background: var(--color-cream);
  color: var(--color-dark);
}

.btn--cream:hover {
  background: var(--color-cream-dark);
  color: var(--color-white);
}

.btn--white {
  background: var(--color-white);
  color: var(--color-dark);
}

.btn--white:hover {
  background: var(--color-warm-bg);
}

.btn--sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-xs);
  min-height: 36px;
}

.btn--lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
  min-height: 52px;
}

.btn--icon {
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: var(--radius-full);
}

/* --- Cards --- */
.card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border-light);
  overflow: hidden;
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-md);
}

.card__image {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background: var(--color-warm-bg-alt);
}

.card__body {
  padding: var(--space-6);
}

/* --- Hero Section --- */
.hero {
  padding: var(--space-16) 0;
  background: linear-gradient(170deg, var(--color-primary-light) 0%, var(--color-cream-light) 100%);
  position: relative;
  overflow: hidden;
}

.hero--dark {
  background: linear-gradient(170deg, var(--color-dark) 0%, #1A3A26 100%);
  color: var(--color-white);
}

.hero--dark h1,
.hero--dark h2,
.hero--dark p {
  color: var(--color-white);
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 600px;
}

.hero__title {
  font-size: var(--text-6xl);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-6);
  line-height: 1.1;
}

.hero__subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-8);
  line-height: 1.6;
}

.hero--dark .hero__subtitle {
  color: rgba(255,255,255,0.8);
}

.hero__actions {
  display: flex;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.hero__visual {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 45%;
  max-width: 600px;
  z-index: 1;
}

/* --- Promo Section --- */
.promo {
  padding: var(--space-16) 0;
}

.promo--alt {
  background: var(--color-warm-bg);
}

.promo--dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.promo--dark h2,
.promo--dark p {
  color: var(--color-white);
}

.promo__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
}

.promo__grid--reverse {
  direction: rtl;
}

.promo__grid--reverse > * {
  direction: ltr;
}

.promo__image {
  width: 100%;
  aspect-ratio: 4/3;
  border-radius: var(--radius-xl);
  object-fit: cover;
  background: var(--color-cream-light);
}

.promo__overline {
  display: inline-block;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-3);
}

.promo__title {
  font-size: var(--text-4xl);
  margin-bottom: var(--space-4);
  letter-spacing: -0.02em;
}

.promo__body {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-6);
  line-height: 1.6;
}

.promo--dark .promo__body {
  color: rgba(255,255,255,0.8);
}

/* --- Feature Cards Grid --- */
.features {
  padding: var(--space-16) 0;
}

.features__header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.features__title {
  font-size: var(--text-4xl);
  margin-bottom: var(--space-4);
}

.features__subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  max-width: 600px;
  margin: 0 auto;
}

.features__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: var(--space-6);
  left: 50%;
  transform: translateX(-50%);
  z-index: 1000;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: var(--space-6);
  max-width: 600px;
  width: calc(100% - var(--space-8));
  display: flex;
  align-items: flex-start;
  gap: var(--space-6);
  border: 1px solid var(--color-border-light);
}

.cookie-banner.hidden {
  display: none;
}

.cookie-banner__icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  background: var(--color-cream-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-cream-dark);
}

.cookie-banner__content {
  flex: 1;
}

.cookie-banner__title {
  font-weight: 700;
  margin-bottom: var(--space-1);
}

.cookie-banner__body {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-4);
  line-height: 1.5;
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-3);
}

/* --- Footer --- */
.footer {
  background: var(--color-dark);
  color: var(--color-white);
  padding: var(--space-16) 0 var(--space-8);
  margin-top: auto;
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-8);
}

.footer__column-title {
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-6);
  color: var(--color-cream);
  cursor: default;
}

.footer__links {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer__link {
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
  line-height: 1.4;
}

.footer__link:hover {
  color: var(--color-cream);
}

.footer__bottom {
  margin-top: var(--space-12);
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer__social {
  display: flex;
  gap: var(--space-4);
}

.footer__social-link {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.7);
  transition: all var(--transition-fast);
}

.footer__social-link:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.footer__muted {
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.5);
}

.footer__accordion-toggle {
  display: none;
}

/* --- Rewards: Tiers --- */
.tiers {
  padding: var(--space-16) 0;
}

.tiers__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.tier-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 2px solid var(--color-border-light);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}

.tier-card:hover {
  border-color: var(--color-cream);
  box-shadow: var(--shadow-lg);
}

.tier-card--featured {
  border-color: var(--color-cream);
  background: linear-gradient(180deg, var(--color-cream-light) 0%, var(--color-white) 40%);
  position: relative;
}

.tier-card__badge {
  display: inline-block;
  background: var(--color-primary);
  color: var(--color-white);
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.tier-card__icon {
  width: 56px;
  height: 56px;
  margin: 0 auto var(--space-4);
  background: var(--color-primary-10);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.tier-card__name {
  font-size: var(--text-xl);
  font-weight: 700;
  margin-bottom: var(--space-2);
}

.tier-card__threshold {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-6);
}

.tier-card__benefits {
  text-align: left;
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
}

.tier-card__benefits li {
  padding: var(--space-2) 0;
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  line-height: 1.4;
}

.tier-card__benefits li::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--color-primary);
  border-radius: var(--radius-full);
  flex-shrink: 0;
  margin-top: 8px;
}

/* --- Rewards: Redemption Tabs --- */
.redemption {
  padding: var(--space-16) 0;
  background: var(--color-warm-bg);
}

.redemption__tabs {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-8);
  overflow-x: auto;
  padding-bottom: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.redemption__tab {
  flex-shrink: 0;
  padding: var(--space-4) var(--space-6);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text-secondary);
  background: var(--color-white);
  border: 2px solid var(--color-border-light);
  transition: all var(--transition-fast);
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.redemption__tab:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.redemption__tab--active {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.redemption__tab-stars {
  display: flex;
  align-items: center;
  gap: 2px;
}

.redemption__panel {
  display: none;
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-md);
  text-align: center;
}

.redemption__panel--active {
  display: block;
}

.redemption__reward-icon {
  width: 72px;
  height: 72px;
  margin: 0 auto var(--space-6);
  background: var(--color-cream-light);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.redemption__reward-title {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-3);
}

.redemption__reward-value {
  display: inline-block;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-primary);
  background: var(--color-primary-10);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.redemption__reward-body {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  max-width: 480px;
  margin: 0 auto var(--space-6);
}

/* --- Gift Cards --- */
.gift-hero {
  padding: var(--space-16) 0;
  background: linear-gradient(170deg, var(--color-dark) 0%, #1A3A26 100%);
  color: var(--color-white);
  text-align: center;
}

.gift-hero__title {
  font-size: var(--text-5xl);
  color: var(--color-white);
  margin-bottom: var(--space-4);
}

.gift-hero__subtitle {
  font-size: var(--text-lg);
  color: rgba(255,255,255,0.8);
  max-width: 600px;
  margin: 0 auto var(--space-8);
}

/* Carousel */
.carousel {
  position: relative;
  padding: var(--space-12) 0;
}

.carousel__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-6);
}

.carousel__title {
  font-size: var(--text-2xl);
}

.carousel__controls {
  display: flex;
  gap: var(--space-2);
}

.carousel__btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text);
  transition: all var(--transition-fast);
  background: var(--color-white);
}

.carousel__btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  background: var(--color-primary-10);
}

.carousel__btn:disabled {
  opacity: 0.3;
  cursor: default;
  border-color: var(--color-border);
  color: var(--color-text-muted);
  background: var(--color-white);
}

.carousel__track-wrapper {
  overflow: hidden;
}

.carousel__track {
  display: flex;
  gap: var(--space-6);
  transition: transform var(--transition-slow);
}

.carousel__slide {
  flex: 0 0 calc(25% - var(--space-5));
  min-width: 240px;
}

.gift-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border-light);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.gift-card__image {
  width: 100%;
  aspect-ratio: 16/10;
