  --color-text-muted: #8B8986;
  --color-border: #E0DCD5;
  --color-border-light: #EEEAE3;
  --color-error: #C0392B;
  --color-success: #00824A;
  --color-gold: #D4A76A;
  --color-gold-light: #F9F0E3;
  --color-star: #D4A76A;

  /* Typography */
  --font-heading: 'DM Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'DM Sans', 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;

  /* Font Sizes */
  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Border Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.08), 0 4px 8px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 48px rgba(0,0,0,0.1), 0 8px 16px rgba(0,0,0,0.04);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 200ms ease;
  --transition-slow: 300ms ease;

  /* Layout */
  --max-width: 1280px;
  --header-height: 72px;
}

/* --- Reset --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

main {
  flex: 1;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  font-size: inherit;
}

input, select, textarea {
  font-family: inherit;
  font-size: inherit;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-text);
}

h1 { font-size: var(--text-5xl); }
h2 { font-size: var(--text-4xl); }
h3 { font-size: var(--text-2xl); }
h4 { font-size: var(--text-xl); }
h5 { font-size: var(--text-lg); }
h6 { font-size: var(--text-base); }

/* --- Container --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.container--narrow {
  max-width: 960px;
}

.container--wide {
  max-width: 1440px;
}

/* --- Header / Navigation --- */
.header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border-light);
  height: var(--header-height);
  box-shadow: var(--shadow-sm);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.header__logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: var(--text-xl);
  color: var(--color-primary);
  letter-spacing: -0.02em;
}

.header__logo svg {
  width: 36px;
  height: 36px;
}

.header__nav {
  display: flex;
  align-items: center;
  gap: var(--space-1);
}

.header__nav-link {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.header__nav-link:hover,
.header__nav-link--active {
  color: var(--color-primary);
  background: var(--color-primary-10);
}

.header__actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.header__mobile-toggle {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  color: var(--color-text);
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: var(--text-sm);
  font-weight: 600;
  line-height: 1.5;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
  min-height: 44px;
  letter-spacing: 0.01em;
}

.btn:active {
  transform: scale(0.97);
}

.btn--primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn--primary:hover {
  background: var(--color-primary-hover);
  box-shadow: var(--shadow-md);
}

.btn--outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn--outline:hover {
  background: var(--color-primary-10);
}

.btn--dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.btn--dark:hover {
  background: var(--color-dark-hover);
  box-shadow: var(--shadow-md);
}

.btn--cream {
  background: var(--color-cream);
  color: var(--color-dark);
}

.btn--cream:hover {
  background: var(--color-cream-dark);
  color: var(--color-white);
}

.btn--white {
  background: var(--color-white);
  color: var(--color-dark);
}

.btn--white:hover {
  background: var(--color-warm-bg);
}

.btn--sm {
  padding: var(--space-2) var(--space-4);
  font-size: var(--text-xs);
  min-height: 36px;
}

.btn--lg {
  padding: var(--space-4) var(--space-8);
  font-size: var(--text-base);
  min-height: 52px;
}

.btn--icon {
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: var(--radius-full);
}

/* --- Cards --- */
.card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border-light);
  overflow: hidden;
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-md);
}

.card__image {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
  background: var(--color-warm-bg-alt);
}

.card__body {
  padding: var(--space-6);
}

/* --- Hero Section --- */
.hero {
  padding: var(--space-16) 0;
  background: linear-gradient(170deg, var(--color-primary-light) 0%, var(--color-cream-light) 100%);
  position: relative;
  overflow: hidden;
}

.hero--dark {
  background: linear-gradient(170deg, var(--color-dark) 0%, #1A3A26 100%);
  color: var(--color-white);
}

.hero--dark h1,
.hero--dark h2,
.hero--dark p {
  color: var(--color-white);
}

.hero__content {
  position: relative;
  z-index: 2;
  max-width: 600px;
}

.hero__title {
  font-size: var(--text-6xl);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-6);
  line-height: 1.1;
}

.hero__subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-8);
  line-height: 1.6;
}

.hero--dark .hero__subtitle {
  color: rgba(255,255,255,0.8);
}

.hero__actions {
  display: flex;
  gap: var(--space-4);
  flex-wrap: wrap;
}

.hero__visual {
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 45%;
  max-width: 600px;
  z-index: 1;
}

/* --- Promo Section --- */
.promo {
  padding: var(--space-16) 0;
}

.promo--alt {
  background: var(--color-warm-bg);
}

.promo--dark {
  background: var(--color-dark);
  color: var(--color-white);
}

.promo--dark h2,
.promo--dark p {
  color: var(--color-white);
}

.promo__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-12);
  align-items: center;
}

.promo__grid--reverse {
  direction: rtl;
}

.promo__grid--reverse > * {
  direction: ltr;
}

.promo__image {
  width: 100%;
  aspect-ratio: 4/3;
  border-radius: var(--radius-xl);
  object-fit: cover;
  background: var(--color-cream-light);
}

.promo__overline {
  display: inline-block;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-3);
}

.promo__title {
  font-size: var(--text-4xl);
  margin-bottom: var(--space-4);
  letter-spacing: -0.02em;
}

.promo__body {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-6);
  line-height: 1.6;
}

.promo--dark .promo__body {
  color: rgba(255,255,255,0.8);
}

/* --- Feature Cards Grid --- */
.features {
  padding: var(--space-16) 0;
}

.features__header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.features__title {
  font-size: var(--text-4xl);
  margin-bottom: var(--space-4);
}

.features__subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  max-width: 600px;
  margin: 0 auto;
}

.features__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: var(--space-6);
  left: 50%;
  transform: translateX(-50%);
  z-index: 1000;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: var(--space-6);
  max-width: 600px;
  width: calc(100% - var(--space-8));
  display: flex;
  align-items: flex-start;
  gap: var(--space-6);
  border: 1px solid var(--color-border-light);
}

.cookie-banner.hidden {
  display: none;
}

.cookie-banner__icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  background: var(--color-cream-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-cream-dark);
}

.cookie-banner__content {
  flex: 1;
}

.cookie-banner__title {
  font-weight: 700;
  margin-bottom: var(--space-1);
}

.cookie-banner__body {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-4);
  line-height: 1.5;
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-3);
}

/* --- Footer --- */
.footer {
  background: var(--color-dark);
  color: var(--color-white);
  padding: var(--space-16) 0 var(--space-8);
  margin-top: auto;
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-8);
}

.footer__column-title {
  font-size: var(--text-sm);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-6);
  color: var(--color-cream);
  cursor: default;
}

.footer__links {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.footer__link {
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.7);
  transition: color var(--transition-fast);
  line-height: 1.4;
}

.footer__link:hover {
  color: var(--color-cream);
}

.footer__bottom {
  margin-top: var(--space-12);
  padding-top: var(--space-8);
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-4);
}

.footer__social {
  display: flex;
  gap: var(--space-4);
}

.footer__social-link {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.7);
  transition: all var(--transition-fast);
}

.footer__social-link:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.footer__muted {
  font-size: var(--text-sm);
  color: rgba(255,255,255,0.5);
}

.footer__accordion-toggle {
  display: none;
}

/* --- Rewards: Tiers --- */
.tiers {
  padding: var(--space-16) 0;
}

.tiers__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-6);
}

.tier-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 2px solid var(--color-border-light);
  padding: var(--space-8);
  text-align: center;
  transition: all var(--transition-base);
}

.tier-card:hover {
  border-color: var(--color-cream);
  box-shadow: var(--shadow-lg);
}

.tier-card--featured {
  border-color: var(--color-cream);
  background: linear-gradient(180deg, var(--color-cream-light) 0%, var(--color-white) 40%);
  position: relative;
}

.tier-card__badge {
  display: inline-block;
  background: var(--color-primary);
  color: var(--color-white);
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.tier-card__icon {
  width: 56px;
  height: 56px;
  margin: 0 auto var(--space-4);
  background: var(--color-primary-10);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.tier-card__name {
  font-size: var(--text-xl);
  font-weight: 700;
  margin-bottom: var(--space-2);
}

.tier-card__threshold {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-6);
}

.tier-card__benefits {
  text-align: left;
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
}

.tier-card__benefits li {
  padding: var(--space-2) 0;
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  line-height: 1.4;
}

.tier-card__benefits li::before {
  content: '';
  width: 6px;
  height: 6px;
  background: var(--color-primary);
  border-radius: var(--radius-full);
  flex-shrink: 0;
  margin-top: 8px;
}

/* --- Rewards: Redemption Tabs --- */
.redemption {
  padding: var(--space-16) 0;
  background: var(--color-warm-bg);
}

.redemption__tabs {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-8);
  overflow-x: auto;
  padding-bottom: var(--space-2);
  -webkit-overflow-scrolling: touch;
}

.redemption__tab {
  flex-shrink: 0;
  padding: var(--space-4) var(--space-6);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-text-secondary);
  background: var(--color-white);
  border: 2px solid var(--color-border-light);
  transition: all var(--transition-fast);
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.redemption__tab:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.redemption__tab--active {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.redemption__tab-stars {
  display: flex;
  align-items: center;
  gap: 2px;
}

.redemption__panel {
  display: none;
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: var(--space-10);
  box-shadow: var(--shadow-md);
  text-align: center;
}

.redemption__panel--active {
  display: block;
}

.redemption__reward-icon {
  width: 72px;
  height: 72px;
  margin: 0 auto var(--space-6);
  background: var(--color-cream-light);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-primary);
}

.redemption__reward-title {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-3);
}

.redemption__reward-value {
  display: inline-block;
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--color-primary);
  background: var(--color-primary-10);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--radius-full);
  margin-bottom: var(--space-4);
}

.redemption__reward-body {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  max-width: 480px;
  margin: 0 auto var(--space-6);
}

/* --- Gift Cards --- */
.gift-hero {
  padding: var(--space-16) 0;
  background: linear-gradient(170deg, var(--color-dark) 0%, #1A3A26 100%);
  color: var(--color-white);
  text-align: center;
}

.gift-hero__title {
  font-size: var(--text-5xl);
  color: var(--color-white);
  margin-bottom: var(--space-4);
}

.gift-hero__subtitle {
  font-size: var(--text-lg);
  color: rgba(255,255,255,0.8);
  max-width: 600px;
  margin: 0 auto var(--space-8);
}

/* Carousel */
.carousel {
  position: relative;
  padding: var(--space-12) 0;
}

.carousel__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: var(--space-6);
}

.carousel__title {
  font-size: var(--text-2xl);
}

.carousel__controls {
  display: flex;
  gap: var(--space-2);
}

.carousel__btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  border: 2px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text);
  transition: all var(--transition-fast);
  background: var(--color-white);
}

.carousel__btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  background: var(--color-primary-10);
}

.carousel__btn:disabled {
  opacity: 0.3;
  cursor: default;
  border-color: var(--color-border);
  color: var(--color-text-muted);
  background: var(--color-white);
}

.carousel__track-wrapper {
  overflow: hidden;
}

.carousel__track {
  display: flex;
  gap: var(--space-6);
  transition: transform var(--transition-slow);
}

.carousel__slide {
  flex: 0 0 calc(25% - var(--space-5));
  min-width: 240px;
}

.gift-card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border-light);
  overflow: hidden;
  transition: all var(--transition-base);
  cursor: pointer;
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.gift-card__image {
  width: 100%;
  aspect-ratio: 16/10;
  object-fit: cover;
  background: linear-gradient(135deg, var(--color-cream-light), var(--color-primary-light));
  display: flex;
  align-items: center;
  justify-content: center;
}

.gift-card__body {
  padding: var(--space-4);
}

.gift-card__name {
  font-size: var(--text-sm);
  font-weight: 600;
  margin-bottom: var(--space-1);
}

.gift-card__category {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
}

/* --- Store Locator --- */
.store-locator {
  padding: var(--space-8) 0 var(--space-16);
}

.store-locator__controls {
  display: flex;
  gap: var(--space-4);
  margin-bottom: var(--space-6);
  flex-wrap: wrap;
}

.store-locator__order-type {
  display: flex;
  background: var(--color-warm-bg);
  border-radius: var(--radius-full);
  padding: 3px;
}

.store-locator__type-btn {
  padding: var(--space-2) var(--space-5);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: all var(--transition-fast);
  min-height: 40px;
}

.store-locator__type-btn--active {
  background: var(--color-white);
  color: var(--color-primary);
  box-shadow: var(--shadow-sm);
}

.store-locator__search-wrap {
  position: relative;
  flex: 1;
  min-width: 240px;
}

.store-locator__search {
  width: 100%;
  padding: var(--space-3) var(--space-4) var(--space-3) var(--space-12);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: var(--text-base);
  background: var(--color-white);
  transition: border-color var(--transition-fast);
  min-height: 48px;
}

.store-locator__search:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 4px var(--color-primary-20);
}

.store-locator__search-icon {
  position: absolute;
  left: var(--space-4);
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-text-muted);
  pointer-events: none;
}

.store-locator__filter-btn {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-5);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-full);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--color-text);
  background: var(--color-white);
  transition: all var(--transition-fast);
  min-height: 48px;
}

.store-locator__filter-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
}

.store-locator__body {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-6);
  min-height: 500px;
}

.store-locator__map {
  background: var(--color-warm-bg-alt);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border-light);
  overflow: hidden;
  min-height: 500px;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}

.store-locator__map-placeholder {
  text-align: center;
  padding: var(--space-8);
}

.store-locator__map-placeholder svg {
  width: 80px;
  height: 80px;
  color: var(--color-text-muted);
  margin-bottom: var(--space-4);
}

.store-locator__map-placeholder p {
  font-size: var(--text-sm);
  color: var(--color-text-muted);
}

.store-results {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  max-height: 500px;
  overflow-y: auto;
}

.store-card {
  background: var(--color-white);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  padding: var(--space-5);
  transition: all var(--transition-fast);
}

.store-card:hover {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-md);
}

.store-card__name {
  font-weight: 600;
  margin-bottom: var(--space-2);
}

.store-card__address {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-2);
}

.store-card__hours {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
  margin-bottom: var(--space-3);
}

.store-card__features {
  display: flex;
  gap: var(--space-2);
  flex-wrap: wrap;
}

.store-card__feature {
  font-size: var(--text-xs);
  font-weight: 500;
  padding: var(--space-1) var(--space-2);
  background: var(--color-primary-10);
  color: var(--color-primary);
  border-radius: var(--radius-sm);
}

/* Filter Panel */
.filter-panel {
  display: none;
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-border-light);
  padding: var(--space-6);
  margin-bottom: var(--space-6);
  box-shadow: var(--shadow-md);
}

.filter-panel--open {
  display: block;
}

.filter-panel__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-4);
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-sm);
  cursor: pointer;
  padding: var(--space-2);
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast);
}

.filter-option:hover {
  background: var(--color-warm-bg);
}

.filter-option input[type="checkbox"] {
  accent-color: var(--color-primary);
  width: 18px;
  height: 18px;
}

/* --- Menu Page --- */
.menu-page {
  padding: var(--space-8) 0 var(--space-16);
}

.menu-page__layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-10);
  align-items: start;
}

.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-8));
}

.menu-sidebar__section {
  margin-bottom: var(--space-6);
}

.menu-sidebar__title {
  font-size: var(--text-xs);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-muted);
  margin-bottom: var(--space-3);
}

.menu-sidebar__link {
  display: block;
  padding: var(--space-2) var(--space-3);
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  margin-bottom: 1px;
}

.menu-sidebar__link:hover,
.menu-sidebar__link--active {
  background: var(--color-primary-10);
  color: var(--color-primary);
}

.menu-main__section {
  margin-bottom: var(--space-12);
}

.menu-main__title {
  font-size: var(--text-3xl);
  margin-bottom: var(--space-2);
}

.menu-main__subtitle {
  font-size: var(--text-base);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-6);
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-4);
}

.menu-item {
  display: flex;
  gap: var(--space-4);
  background: var(--color-white);
  border: 1px solid var(--color-border-light);
  border-radius: var(--radius-md);
  padding: var(--space-4);
  transition: all var(--transition-fast);
}

.menu-item:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--color-cream);
}

.menu-item__image {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-md);
  background: var(--color-warm-bg-alt);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-cream-dark);
}

.menu-item__info {
  flex: 1;
}

.menu-item__name {
  font-weight: 600;
  font-size: var(--text-sm);
  margin-bottom: var(--space-1);
}

.menu-item__desc {
  font-size: var(--text-xs);
  color: var(--color-text-muted);
  line-height: 1.4;
}

/* Breadcrumb */
.breadcrumb {
  display: flex;
  gap: var(--space-2);
  align-items: center;
  font-size: var(--text-sm);
  color: var(--color-text-muted);
  padding: var(--space-4) 0;
}

.breadcrumb a {
  color: var(--color-primary);
}

.breadcrumb a:hover {
  text-decoration: underline;
}

.breadcrumb__sep {
  color: var(--color-border);
}

/* --- How It Works --- */
.steps {
  padding: var(--space-16) 0;
}

.steps__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-8);
}

.step-card {
  text-align: center;
}

.step-card__number {
  width: 56px;
  height: 56px;
  margin: 0 auto var(--space-4);
  background: var(--color-primary);
  color: var(--color-white);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-xl);
  font-weight: 700;
}

.step-card__title {
  font-weight: 700;
  margin-bottom: var(--space-2);
}

.step-card__body {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  line-height: 1.5;
}

/* --- Partnerships --- */
.partnerships {
  padding: var(--space-12) 0;
  background: var(--color-warm-bg);
}

.partnerships__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
}

.partner-card {
  display: flex;
  align-items: center;
  gap: var(--space-5);
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  border: 1px solid var(--color-border-light);
}

.partner-card__logo {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: var(--color-warm-bg-alt);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: var(--text-lg);
  color: var(--color-primary);
}

.partner-card__body {
  font-size: var(--text-sm);
  color: var(--color-text-secondary);
  line-height: 1.5;
}

.partner-card__body strong {
  color: var(--color-text);
}

/* --- FAQ / Info Sections --- */
.info-section {
  padding: var(--space-12) 0;
}

.info-section__title {
  font-size: var(--text-2xl);
  margin-bottom: var(--space-6);
}

.info-section__body {
  font-size: var(--text-base);
  color: var(--color-text-secondary);
  line-height: 1.7;
  max-width: 720px;
}

.info-section__body p {
  margin-bottom: var(--space-4);
}

/* --- Utility --- */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.text-center { text-align: center; }
.text-primary { color: var(--color-primary); }
.text-muted { color: var(--color-text-secondary); }
.mb-0 { margin-bottom: 0; }
.mb-4 { margin-bottom: var(--space-4); }
.mb-6 { margin-bottom: var(--space-6); }
.mb-8 { margin-bottom: var(--space-8); }
.mt-8 { margin-top: var(--space-8); }

/* --- Section Divider --- */
.section-divider {
  height: 1px;
  background: var(--color-border-light);
  margin: 0;
  border: none;
}

/* --- Download App Banner --- */
.app-banner {
  padding: var(--space-12) 0;
  background: var(--color-dark);
  color: var(--color-white);
  text-align: center;
}

.app-banner__title {
  font-size: var(--text-3xl);
  color: var(--color-white);
  margin-bottom: var(--space-3);
}

.app-banner__body {
  color: rgba(255,255,255,0.8);
  margin-bottom: var(--space-6);
  font-size: var(--text-lg);
}

.app-banner__buttons {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  flex-wrap: wrap;
}

/* --- Terms --- */
.terms {
  padding: var(--space-8) 0;
  font-size: var(--text-xs);
  color: var(--color-text-muted);
  line-height: 1.6;
}

.terms a {
  color: var(--color-primary);
  text-decoration: underline;
}

/* --- Business Gifting --- */
.business-gifting {
  padding: var(--space-16) 0;
  background: var(--color-warm-bg);
}

.business-gifting__card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: var(--space-10);
  text-align: center;
  box-shadow: var(--shadow-md);
  max-width: 700px;
  margin: 0 auto;
}

/* --- Suggestions dropdown --- */
.suggestions {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  background: var(--color-white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  border: 1px solid var(--color-border-light);
  z-index: 10;
  overflow: hidden;
  display: none;
}

.suggestions--open {
  display: block;
}

.suggestions__item {
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-sm);
  cursor: pointer;
  transition: background var(--transition-fast);
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.suggestions__item:hover {
  background: var(--color-warm-bg);
}

/* --- Mobile Nav Drawer --- */
.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  z-index: 99;
  padding: var(--space-6);
  overflow-y: auto;
}

.mobile-nav--open {
  display: block;
}

.mobile-nav__link {
  display: block;
  padding: var(--space-4);
  font-size: var(--text-lg);
  font-weight: 500;
  color: var(--color-text);
  border-radius: var(--radius-md);
  transition: background var(--transition-fast);
}

.mobile-nav__link:hover {
  background: var(--color-warm-bg);
}

.mobile-nav__actions {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  margin-top: var(--space-6);
  padding-top: var(--space-6);
  border-top: 1px solid var(--color-border-light);
}

/* --- Page Hero (generic for interior pages) --- */
.page-hero {
  padding: var(--space-12) 0;
  background: linear-gradient(170deg, var(--color-primary-light) 0%, var(--color-cream-light) 100%);
  text-align: center;
}

.page-hero--dark {
  background: linear-gradient(170deg, var(--color-dark) 0%, #1A3A26 100%);
  color: var(--color-white);
}

.page-hero__title {
  font-size: var(--text-5xl);
  margin-bottom: var(--space-4);
}

.page-hero--dark .page-hero__title {
  color: var(--color-white);
}

.page-hero__subtitle {
  font-size: var(--text-lg);
  color: var(--color-text-secondary);
  max-width: 600px;
  margin: 0 auto var(--space-6);
}

.page-hero--dark .page-hero__subtitle {
  color: rgba(255,255,255,0.8);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  h1 { font-size: var(--text-4xl); }
  h2 { font-size: var(--text-3xl); }

  .hero__title { font-size: var(--text-4xl); }
  .promo__title { font-size: var(--text-3xl); }
  .features__grid { grid-template-columns: repeat(2, 1fr); }
  .tiers__grid { grid-template-columns: 1fr; }
  .steps__grid { grid-template-columns: 1fr; }
  .partnerships__grid { grid-template-columns: 1fr; }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }

  .promo__grid {
    grid-template-columns: 1fr;
    gap: var(--space-8);
  }

  .promo__grid--reverse {
    direction: ltr;
  }

  .store-locator__body {
    grid-template-columns: 1fr;
  }

  .store-locator__map {
    min-height: 300px;
  }

  .carousel__slide {
    flex: 0 0 calc(33.333% - var(--space-4));
  }

  .menu-page__layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
    display: flex;
    gap: var(--space-4);
    overflow-x: auto;
    padding-bottom: var(--space-2);
    -webkit-overflow-scrolling: touch;
  }

  .menu-sidebar__section {
    margin-bottom: 0;
    flex-shrink: 0;
  }
}

@media (max-width: 768px) {
  :root {
    --header-height: 64px;
  }

  h1 { font-size: var(--text-3xl); }
  h2 { font-size: var(--text-2xl); }
  h3 { font-size: var(--text-xl); }

  .header__nav { display: none; }
  .header__actions .btn { display: none; }
  .header__actions .btn--sm { display: inline-flex; }
  .header__mobile-toggle { display: flex; }

  .hero {
    padding: var(--space-10) 0;
  }

  .hero__title {
    font-size: var(--text-3xl);
  }

  .hero__visual {
    display: none;
  }

  .hero__content {
    max-width: 100%;
  }

  .promo {
    padding: var(--space-10) 0;
  }

  .promo__title {
    font-size: var(--text-2xl);
  }

  .features__grid {
    grid-template-columns: 1fr;
  }

  .footer__grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer__column {
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }

  .footer__accordion-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: var(--space-4) 0;
    color: var(--color-cream);
    font-size: var(--text-sm);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    background: none;
    border: none;
    cursor: pointer;
    min-height: 44px;
  }

  .footer__accordion-toggle svg {
    transition: transform var(--transition-fast);
  }

  .footer__accordion-toggle[aria-expanded="true"] svg {
    transform: rotate(180deg);
  }

  .footer__column-title {
    display: none;
  }

  .footer__links {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--transition-slow);
  }

  .footer__links--open {
    max-height: 500px;
    padding-bottom: var(--space-4);
  }

  .carousel__slide {
    flex: 0 0 calc(50% - var(--space-3));
    min-width: 180px;
  }

  .cookie-banner {
    flex-direction: column;
    bottom: var(--space-4);
  }

  .store-locator__controls {
    flex-direction: column;
  }

  .store-locator__search-wrap {
    min-width: 100%;
  }

  .menu-grid {
    grid-template-columns: 1fr;
  }

  .redemption__tabs {
    gap: var(--space-1);
  }

  .redemption__tab {
    padding: var(--space-3) var(--space-4);
    font-size: var(--text-xs);
  }

  .tier-card {
    padding: var(--space-6);
  }

  .redemption__panel {
    padding: var(--space-6);
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0 var(--space-4);
  }

  .carousel__slide {
    flex: 0 0 85%;
    min-width: 220px;
  }

  .gift-hero__title {
    font-size: var(--text-3xl);
  }

  .page-hero__title {
    font-size: var(--text-3xl);
  }

  .hero__actions {
    flex-direction: column;
  }

  .hero__actions .btn {
    width: 100%;
  }
}

/* --- Reduced Motion --- */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* --- Focus States --- */
:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.btn:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 3px;
}

/* --- Star Rating --- */
.stars {
  display: flex;
  align-items: center;
  gap: 1px;
}

.stars svg {
  width: 16px;
  height: 16px;
  color: var(--color-star);
}

/* --- Scrollbar --- */
.store-results::-webkit-scrollbar {
  width: 6px;
}
.store-results::-webkit-scrollbar-track {
  background: transparent;
}
.store-results::-webkit-scrollbar-thumb {
  background: var(--color-border);
  border-radius: 3px;
}
